Here is the commit message:
Fix use-after-free bug when running e.g. `echo xyz | dte
 -cquit`

This bug was introduced by commit 4df5fce16ceb245b and was due to
`std_buffer` being fully freed by `free_buffer()`, in between the
calls to `init_std_buffer()` and `buffer_write_blocks_and_free()`,
when `std_buffer->stdout_buffer` was false.

This commit also adds some tests that should prevent regressions
(especially when combined with AddressSanitizer).

Here is the root cause:
The bug was caused by `std_buffer` being fully freed by `free_buffer()` between the calls to `init_std_buffer()` and `buffer_write_blocks_and_free()`, specifically when `std_buffer->stdout_buffer` was false. This led to a use-after-free situation where the program attempted to access a freed memory location, resulting in undefined behavior.

Here is the patch:
 // NOLINTNEXTLINE(readability-function-size)
 int main(int argc, char *argv[])
 {
     static const char optstring[] = "hBHKRVS:b:c:t:r:s:";
     const char *rc = NULL;
     const char *commands[8];
     const char *tags[8];
     size_t nr_commands = 0;
     size_t nr_tags = 0;
     bool read_rc = true;
     bool use_showkey = false;
     bool load_and_save_history = true;
     errors_to_stderr(true);

     for (int ch; (ch = getopt(argc, argv, optstring)) != -1; ) {
         switch (ch) {
         case 'c':
             if (unlikely(nr_commands >= ARRAYLEN(commands))) {
                 fputs("Error: too many -c options used\n", stderr);
                 return EC_USAGE_ERROR;
             }
             commands[nr_commands++] = optarg;
             break;
         case 't':
             if (unlikely(nr_tags >= ARRAYLEN(tags))) {
                 fputs("Error: too many -t options used\n", stderr);
                 return EC_USAGE_ERROR;
             }
             tags[nr_tags++] = optarg;
             break;
         case 'r':
             rc = optarg;
             break;
         case 's':
         case 'S':
             return lint_syntax(optarg, ch == 'S' ? SYN_LINT : 0);
         case 'R':
             read_rc = false;
             break;
         case 'b':
             return dump_builtin_config(optarg);
         case 'B':
             return list_builtin_configs();
         case 'H':
             load_and_save_history = false;
             break;
         case 'K':
             use_showkey = true;
             goto loop_break;
         case 'V':
             return write_stdout(copyright, sizeof(copyright));
         case 'h':
             printf(usage, progname(argc, argv, "dte"));
             return EC_OK;
         default:
             return EC_USAGE_ERROR;
         }
     }

 loop_break:;

     // This must be done before calling init_logging(), otherwise an
     // invocation like e.g. `DTE_LOG=/dev/pts/2 dte 0<&-` could
     // cause the logging fd to be opened as STDIN_FILENO
     int std_fds[2] = {-1, -1};
     ExitCode r = init_std_fds(std_fds);
     if (unlikely(r != EC_OK)) {
         return r;
     }

     r = init_logging(getenv("DTE_LOG"), getenv("DTE_LOG_LEVEL"));
     if (unlikely(r != EC_OK)) {
         return r;
     }

     LOG_INFO("dte version: " VERSION);
     LOG_INFO("build vars:%s", buildvar_string);

     if (!term_mode_init()) {
         perror("tcgetattr");
         return EC_IO_ERROR;
     }

     const char *term_name = getenv("TERM");
     const char *colorterm = getenv("COLORTERM");
     if (use_showkey) {
         LOG_INFO("entering \"showkey\" mode (dte -K)");
         return showkey_loop(term_name, colorterm);
     }

     EditorState *e = init_editor_state();
     Terminal *term = &e->terminal;
     term_init(term, term_name, colorterm);
     Buffer *std_buffer = init_std_buffer(e, std_fds);
+    bool have_stdout_buffer = std_buffer && std_buffer->stdout_buffer;

     // Create this early (needed if "lock-files" is true)
     const char *cfgdir = e->user_config_dir;
     BUG_ON(!cfgdir);
     if (mkdir(cfgdir, 0755) != 0 && errno != EEXIST) {
         error_msg("Error creating %s: %s", cfgdir, strerror(errno));
         load_and_save_history = false;
         e->options.lock_files = false;
     }

     term_save_title(term);
     exec_builtin_rc(e);

     if (read_rc) {
         ConfigFlags flags = CFG_NOFLAGS;
         char buf[8192];
         if (rc) {
             flags |= CFG_MUST_EXIST;
         } else {
             xsnprintf(buf, sizeof buf, "%s/%s", cfgdir, "rc");
             rc = buf;
         }
         LOG_INFO("loading configuration from %s", rc);
         read_normal_config(e, rc, flags);
     }

     log_config_counts(e);
     update_all_syntax_styles(&e->syntaxes, &e->styles);

     Window *window = new_window(e);
     e->window = window;
     e->root_frame = new_root_frame(window);

     set_signal_handlers();
     set_fatal_error_cleanup_handler(cleanup_handler, e);

     if (load_and_save_history) {
         read_history_files(e);
     }

     // We don't want errors relating to opening files printed to stderr,
     // since wildcard arguments (e.g. `dte *`) may expand to directory
     // names and produce lots of "not a regular file" errors
     unsigned int nr_stderr_errors = get_nr_errors();
     errors_to_stderr(false);
     clear_error();

     e->status = EDITOR_RUNNING;

     for (size_t i = optind, line = 0, col = 0; i < argc; i++) {
         const char *str = argv[i];
         if (line == 0 && *str == '+' && str_to_filepos(str + 1, &line, &col)) {
             continue;
         }
         View *view = window_open_buffer(window, str, false, NULL);
         if (line == 0) {
             continue;
         }
         set_view(view);
         move_to_filepos(view, line, col);
         line = 0;
     }

     if (std_buffer) {
         window_add_buffer(window, std_buffer);
     }

     View *dview = NULL;
     if (window->views.count == 0) {
         // Open a default buffer, if none were opened for arguments
         dview = window_open_empty_buffer(window);
         BUG_ON(!dview);
         BUG_ON(window->views.count != 1);
         BUG_ON(dview != window->views.ptrs[0]);
     }

     set_view(window->views.ptrs[0]);

     for (size_t i = 0; i < nr_commands; i++) {
         handle_normal_command(e, commands[i], false);
     }

     int exit_code = e->status;
     bool skipped_mainloop = false;
     if (exit_code >= 0) {
         // If a -c command caused the editor to exit (quit, close -q, etc.),
         // terminal init/deinit and entering the main-loop can be skipped
         skipped_mainloop = true;
         goto exit;
     }

     size_t opened_tags = 0;
     for (size_t i = 0; i < nr_tags; i++) {
         StringView tag_sv = strview_from_cstring(tags[i]);
         // TODO: Split `tag_lookup()` into multiple functions, to avoid
         // duplicated clearing/loading in cases like this
         if (tag_lookup(&e->tagfile, &tag_sv, NULL, &e->messages)) {
             if (activate_current_message(&e->messages, e->window)) {
                 opened_tags++;
             }
         }
     }

     if (dview && nr_commands == 0 && opened_tags > 0) {
         // Close default/empty buffer, if `-t` jumped to a tag and no
         // commands were executed via `-c`
         BUG_ON(window->views.count < 2);
         remove_view(dview);
         dview = NULL;
     }

     if (unlikely(!term_raw())) {
         perror("tcsetattr");
         return EC_IO_ERROR;
     }

     if (unlikely(nr_stderr_errors > 0)) {
         // Display "press any key to continue" prompt for stderr errors
         any_key(term, e->options.esc_timeout);
     }

     ui_start(e);
     term_put_queries(term);
     term_output_flush(&term->obuf);
     exit_code = main_loop(e);
     term_restore_title(term);

     /*
      * This is normally followed immediately by term_cooked() in other
      * contexts, but in this case we want to switch back to cooked mode
      * as late as possible. On underpowered machines, unlocking files and
      * writing history may take some time. If cooked mode were switched
      * to here it'd leave a window of time where we've switched back to
      * the normal screen buffer and reset the termios ECHO flag while
      * still being the foreground process, which would cause any input
      * to be echoed to the terminal (before the shell takes over again
      * and prints its prompt).
      */
     ui_end(e);

